"""Paper 3 case studies.

7132/3 = one compulsory case study (Insert) followed by six questions:
  Q1 12 (analyse)  Q2 12 (analyse)  Q3 16  Q4 16  Q5 20  Q6 24 ('all businesses' synoptic)
AO splits: 12 = AO1 3/AO2 3/AO3 6; 16 = 2/3/4/7; 20 = 4/3/5/8; 24 = 5/4/6/9.
"""


def T(title, headers, rows, note=""):
    return {"title": title, "headers": headers, "rows": rows, "note": note}


def AQ(num, question, spec, demands, indicative, notes=None):
    return {"num": num, "marks": 12, "kind": "analyse", "question": question, "spec": spec,
            "demands": demands, "indicative": indicative, "notes": notes or []}


def EQ(num, marks, question, spec, demands, for_args, against_args, evaluation, calcs=None, notes=None):
    return {"num": num, "marks": marks, "kind": "evaluate", "question": question, "spec": spec, "demands": demands,
            "for_args": for_args, "against_args": against_args, "evaluation": evaluation,
            "calcs": calcs or [], "notes": notes or []}


